{ config, pkgs, inputs, lib, ... }: let
  flakeInputs = lib.filterAttrs (_: lib.isType "flake") inputs;
  bespoke-zellij = inputs.dim-unfocused.packages.x86_64-linux;
  zellij-main = bespoke-zellij.zellij;
  dim-unfocused-wasm = bespoke-zellij.dim-unfocused;
  llm-agents = inputs.llm-agents.packages.x86_64-linux;
  mdv = inputs.mdv.packages.${pkgs.stdenv.hostPlatform.system}.default;
  merman = inputs.merman.packages.${pkgs.stdenv.hostPlatform.system}.default;
  mcp = import ./mcp.nix { inherit pkgs lib; };
  agentDirenv = import ./agent-direnv.nix { inherit pkgs; };
  codex-cfg = import ./codex.nix { inherit lib; };
  agentPermissions = import ./agent-permissions.nix { inherit lib; };
  copilot-cfg = import ./copilot.nix { inherit lib agentDirenv mcp agentPermissions; };
  grok-cfg = import ./grok.nix { inherit lib grok; inherit (mcp) servers; };
  docTools = import ./doc-tools.nix { inherit pkgs; };
  entirePlugins = import ./entire-plugins.nix { inherit pkgs lib; };
  claude = pkgs.writeShellApplication {
    name = "claude";
    runtimeInputs = [ llm-agents.claude-code ] ++ docTools.tools;
    # `=` form is required: --mcp-config is variadic and would otherwise consume
    # subsequent positional args as additional config files.
    #
    # `--effort xhigh` rather than CLAUDE_CODE_EFFORT_LEVEL=xhigh: the env var
    # is consulted ahead of everything else and pins the session, so /effort
    # just refuses ("Not applied: CLAUDE_CODE_EFFORT_LEVEL=xhigh overrides
    # effort this session"). The flag only seeds the session's starting level,
    # leaving /effort free to change it. The `effortLevel` setting is not an
    # option either: /effort saves its pick there, so later sessions would start
    # at whatever level was picked last instead of xhigh.
    # Placed before "$@" because the last --effort wins, so an explicit
    # `claude --effort high` still overrides this default.
    text = ''
      # Load each project's direnv environment before every Bash command.
      export CLAUDE_ENV_FILE=${agentDirenv.loader}
      exec claude --mcp-config=${mcp.claudeMcpConfig} --effort xhigh "$@" \
        --disallowedTools=${lib.escapeShellArg (lib.concatStringsSep "," agentPermissions.claudeDeny)}
    '';
  };
  codex = pkgs.writeShellApplication {
    name = "codex";
    # agentDirenv.bash first: Codex runs commands with the first bash on PATH.
    runtimeInputs = [ agentDirenv.bash llm-agents.codex ] ++ docTools.tools;
    text = ''exec codex ${lib.concatStringsSep " " (mcp.codexArgs ++ codex-cfg.configArgs)} "$@"'';
  };
  copilot = pkgs.writeShellApplication {
    name = "copilot";
    runtimeInputs = [ llm-agents.copilot-cli ] ++ docTools.tools;
    # See home/copilot.nix.
    text = copilot-cfg.wrapperText;
  };
  agy = llm-agents.antigravity-cli;
  grok = llm-agents.grok;
  # llm-agents builds only cmd/entire, but upstream releases also ship
  # git-remote-entire, the git remote helper for entire:// URLs.
  entire = llm-agents.entire.overrideAttrs (old: {
    subPackages = old.subPackages ++ [ "./cmd/git-remote-entire" ];
  });
  # nixpkgs.linear is the macOS desktop app; llm-agents does not package the
  # CLI yet. Pin the upstream Linux binary until it has a maintained Nix package.
  linear-cli = pkgs.stdenvNoCC.mkDerivation (finalAttrs: {
    pname = "linear-cli";
    version = "3.1.0";
    src = pkgs.fetchurl {
      url = "https://github.com/schpet/linear-cli/releases/download/v${finalAttrs.version}/linear-x86_64-unknown-linux-gnu.tar.xz";
      hash = "sha256-v3cSCXzmoB6KN53oNX7KZtV0gFAgHTNrp4e2rTaH8+c=";
    };
    nativeBuildInputs = [ pkgs.autoPatchelfHook pkgs.makeWrapper pkgs.installShellFiles ];
    buildInputs = [ pkgs.stdenv.cc.cc.lib ];
    dontBuild = true;
    installPhase = ''
      runHook preInstall
      install -Dm755 linear "$out/bin/linear"
      install -Dm644 LICENSE "$out/share/licenses/linear-cli/LICENSE"
      install -Dm644 THIRD_PARTY_LICENSES.md "$out/share/licenses/linear-cli/THIRD_PARTY_LICENSES.md"
      runHook postInstall
    '';
    postFixup = ''
      # Patch the ELF interpreter before running the binary for completions.
      autoPatchelf "$out/bin/linear"
      installShellCompletion --cmd linear \
        --bash <("$out/bin/linear" completions bash) \
        --zsh <("$out/bin/linear" completions zsh) \
        --fish <("$out/bin/linear" completions fish)
      wrapProgram "$out/bin/linear" --suffix PATH : ${lib.makeBinPath [ pkgs.libsecret ]}
    '';
    meta = {
      description = "Command-line interface for the Linear issue tracker";
      homepage = "https://github.com/schpet/linear-cli";
      license = lib.licenses.isc;
      mainProgram = "linear";
      platforms = [ "x86_64-linux" ];
      sourceProvenance = [ lib.sourceTypes.binaryNativeCode ];
    };
  });
  open-browser = pkgs.writeShellApplication {
    name = "open-browser";
    text = builtins.readFile ../scripts/open-browser.sh;
  };
  # Tools that exec `xdg-open` directly (ignoring $BROWSER) get a working one.
  # runtimeInputs pins open-browser by store path, so this does not depend on
  # the user profile being on PATH.
  xdg-open = pkgs.writeShellApplication {
    name = "xdg-open";
    runtimeInputs = [ open-browser ];
    text = builtins.readFile ../scripts/xdg-open.sh;
  };
  # mdv that draws ```mermaid fences as diagrams, for yazi's markdown preview.
  mdv-mermaid = pkgs.writeShellApplication {
    name = "mdv";
    runtimeInputs = [ mdv merman pkgs.jq ];
    text = builtins.readFile ../scripts/mdv-mermaid.sh;
  };
  googleCloudSdkWithGke = import ./google-cloud-sdk.nix { inherit pkgs; };
  # Consomme's localhost relay cannot forward Node's default dual-stack [::]
  # listener to Windows (microsoft/WSL#41860). Firebase's OAuth callback uses
  # exactly that binding; IPv4 loopback preserves the normal browser login.
  # portfinder also probes the port by binding and instantly closing it on every
  # address. The relay keeps a phantom listener for each probe for about a
  # minute, and a later bind of a different IPv4 address on that port is
  # silently moved to a random port, so the redirect to localhost:9005 finds
  # nothing. Probing only 127.0.0.1 keeps the probe and the listener identical.
  firebase-tools = pkgs.firebase-tools.overrideAttrs (old: {
    postInstall = (old.postInstall or "") + ''
      substituteInPlace "$out/lib/node_modules/firebase-tools/lib/auth.js" \
        --replace-fail 'server.listen(port, () => {' \
                       'server.listen(port, "127.0.0.1", () => {' \
        --replace-fail 'const getPort = portfinder.getPortPromise;' \
                       'const getPort = async () => { const hosts = portfinder._defaultHosts; portfinder._defaultHosts = ["127.0.0.1"]; try { return await portfinder.getPortPromise(); } finally { portfinder._defaultHosts = hosts; } };'
    '';
  });
  expectedDotfiles = [
    ".ssh" ".cache" ".local" ".config" ".claude" ".gemini" ".grok"
    ".zsh_history" ".zoxide.db" ".zoxide.db.zo" ".sudo_as_admin_successful"
    ".init-gh-completed" ".zcompdump*" ".zsh_sessions" ".wget-hsts" "src"
    ".nix-profile" ".nix-defexpr" ".nix-channels"
    ".bashrc" ".bash_logout" ".bash_history" ".profile"
  ];
  isMinimal = builtins.getEnv "MINIMAL_ENV" != "";
in {
  imports = [ ./shell.nix ./skills.nix ] ++ lib.optionals (!isMinimal) [ ./bookcreator.nix ];

  home.stateVersion = "26.05";

  nix = {
    package = lib.mkDefault pkgs.nix;
    settings = {
      experimental-features = [ "nix-command" "flakes" ];
      flake-registry = "";
      extra-substituters = [ "https://cache.numtide.com" ];
      extra-trusted-public-keys = [ "niks3.numtide.com-1:REDACTED" ];
    };
    registry = lib.mapAttrs (_: flake: {inherit flake;}) flakeInputs;
    nixPath = lib.mapAttrsToList (n: _: "${n}=flake:${n}") flakeInputs;
  };

  home.activation.windowsterminal = lib.hm.dag.entryAfter ["writeBoundary"] ''
    # Glob over user profiles (LocalState is created lazily on WT's first
    # launch, so gating on it would silently no-op on freshly-imaged Windows
    # boxes where the user opened wsl from cmd.exe before ever opening WT).
    for user_dir in /mnt/c/Users/*; do
      [ -f "$user_dir/NTUSER.DAT" ] || continue
      [ -w "$user_dir" ] || continue
      wt_dir="$user_dir/AppData/Local/Packages/Microsoft.WindowsTerminal_8wekyb3d8bbwe/LocalState"
      mkdir -p "$wt_dir" || continue
      ${pkgs.gnused}/bin/sed 's/\x1b/\\u001b/g' ${../config/windows-terminal.json} \
        > "$wt_dir/settings.json"
    done
  '';

  home.activation.wslconfig = lib.hm.dag.entryAfter ["writeBoundary"] ''
    for user_dir in /mnt/c/Users/*; do
      [ -f "$user_dir/NTUSER.DAT" ] || continue
      [ -w "$user_dir" ] || continue
      install -m 0644 ${../config/wslconfig} "$user_dir/.wslconfig"
    done
  '';

  # Keep the diagnostic/recovery tool on Windows so it remains available when
  # WSL cannot start or its network backend is stuck.
  home.activation.wslNetwork = lib.hm.dag.entryAfter ["writeBoundary"] ''
    for user_dir in /mnt/c/Users/*; do
      [ -f "$user_dir/NTUSER.DAT" ] || continue
      [ -w "$user_dir" ] || continue
      install -D -m 0644 ${../config/windows/wsl-network.ps1} \
        "$user_dir/AppData/Local/wsl-network/wsl-network.ps1"
    done
  '';

  home.activation.chromeDevtoolsShortcut = lib.hm.dag.entryAfter ["writeBoundary"] ''
    powershell=/mnt/c/Windows/System32/WindowsPowerShell/v1.0/powershell.exe
    [ -x "$powershell" ] || exit 0
    for user_dir in /mnt/c/Users/*; do
      [ -f "$user_dir/NTUSER.DAT" ] || continue
      [ -w "$user_dir" ] || continue
      install -d "$user_dir/AppData/Local/chrome-devtools-mcp"
      install -m 0644 ${../config/windows/install-chrome-devtools-shortcut.ps1} \
        "$user_dir/AppData/Local/chrome-devtools-mcp/install-shortcut.ps1"
      ps1_win=$(/sbin/wslpath -w "$user_dir/AppData/Local/chrome-devtools-mcp/install-shortcut.ps1")
      "$powershell" -NoProfile -ExecutionPolicy Bypass -File "$ps1_win" || true
    done
  '';

  # FancyZones lives on the Windows side (PowerToys). Same pattern as
  # windowsterminal: push the repo copy onto every writable Windows profile.
  # applied-layouts.json is keyed by GPU-specific monitor-instance IDs, so a
  # blind overwrite would miss displays on another machine. Stamp the default
  # custom grid onto every device the target already knows; fall back to a
  # straight copy when PowerToys has not created the file yet.
  home.activation.fancyzones = lib.hm.dag.entryAfter ["writeBoundary"] ''
    fancyzones_src=${../config/windows/fancyzones}
    jq=${pkgs.jq}/bin/jq
    for user_dir in /mnt/c/Users/*; do
      [ -f "$user_dir/NTUSER.DAT" ] || continue
      [ -w "$user_dir" ] || continue
      fz_dir="$user_dir/AppData/Local/Microsoft/PowerToys/FancyZones"
      mkdir -p "$fz_dir" || continue
      for f in settings.json custom-layouts.json default-layouts.json \
               layout-hotkeys.json layout-templates.json; do
        install -m 0644 "$fancyzones_src/$f" "$fz_dir/$f"
      done
      dest="$fz_dir/applied-layouts.json"
      src="$fancyzones_src/applied-layouts.json"
      if [ -f "$dest" ] && "$jq" -e '."applied-layouts" | type == "array"' "$dest" >/dev/null 2>&1; then
        "$jq" --slurpfile defaults "$fancyzones_src/default-layouts.json" '
          ($defaults[0]."default-layouts"[0].layout) as $layout
          | ."applied-layouts" |= map(. + {"applied-layout": $layout})
        ' "$dest" > "$dest.tmp" && mv "$dest.tmp" "$dest"
        chmod 0644 "$dest"
      else
        install -m 0644 "$src" "$dest"
      fi
      pt_settings="$user_dir/AppData/Local/Microsoft/PowerToys/settings.json"
      if [ -f "$pt_settings" ] && [ -w "$pt_settings" ]; then
        "$jq" '.enabled.FancyZones = true' "$pt_settings" > "$pt_settings.tmp" \
          && mv "$pt_settings.tmp" "$pt_settings"
        chmod 0644 "$pt_settings"
      fi
    done
  '';

# .dotfiles

A single minimal `seed.wsl` is published from every push to `master`. Importing it
gives you a tiny NixOS-WSL bootstrap that, on first interactive login, asks
which identity to take and `nixos-rebuild boot`s into it.

## Install (NixOS-WSL)

From Windows PowerShell:
```powershell
$tarball = "$env:USERPROFILE\Downloads\seed.wsl"
Invoke-WebRequest -Uri "https://github.com/tteggel/.dotfiles/releases/latest/download/seed.wsl" -OutFile $tarball
wsl --import thixos "$env:USERPROFILE\WSL\thixos" $tarball
wsl -d thixos
# → at the prompt, type `t` for thixos or `y` for yoloixos (YOLO to confirm)
# → seed stages the chosen config and terminates the distro
wsl -d thixos
# → boots into the chosen identity; init-gh / init-yolo completes setup
```

## Architecture

- `seed` — minimal bootstrap; bash login, NOPASSWD wheel sudo, `inputs.self`
  baked at `/etc/seed-source`. Prompts t/y, runs `nixos-rebuild switch --flake
  /etc/seed-source#<choice>` (switch, not boot — activation must rewrite
  `/etc/wsl.conf` *now* so the next launch finds the new default user), marks
  `/var/lib/seed-bootstrap.done`, then `wsl.exe --terminate $WSL_DISTRO_NAME`.
- `thixos` — interactive dev. User `thom` (wheel), Tailscale, full toolchain.
- `yoloixos` — agent sandbox. User `agent` (no wheel), no interop, no
  automount, outbound firewall, 4GB / 200% CPU slice. **One-way: `agent` has
  no sudo, so the image can never be rebuilt.**

## Update

Inside thixos:
```shell
sudo nixos-rebuild switch --flake ~/src/github.com/tteggel/.dotfiles#thixos
```
(Inside yoloixos this is intentionally impossible.)

## Agent permissions and Google Cloud PAM

`nixos/agent-permissions.nix` installs root-owned, read-only system policies for
Codex and Claude Code. These forbid `gcloud pam`, `gcloud alpha pam` and
`gcloud beta pam`. Repository settings and allow rules cannot override the
denies. Claude's bypass-permissions mode is disabled so it cannot skip the policy;
auto mode remains available.

Copilot CLI gets no managed policy. Once a managed policy sets any permission
rule, Copilot asks for every operation that matches none of the rules, so a deny
list alone turned routine reads into "Organization policy requires confirmation"
prompts in autopilot.

Home Manager also installs Codex forbidden rules and adds explicit denies to the
Claude and Copilot launchers, including the standalone profiles. For Copilot,
these launcher denies and the SDK below are the only enforcement. The root-owned
managed policies are installed by NixOS, not standalone Home Manager.

`home/google-cloud-sdk.nix` removes all three PAM command groups from the installed
SDK, including calls with global flags before `pam`. The same package supplies
the GCP helper scripts and keeps the GKE auth plugin. This applies to that SDK;
separately installed SDKs and direct PAM API requests require Google Cloud IAM
restrictions to block them.

Apply with the NixOS rebuild command above, then restart agent sessions. Check the
policy and SDK offline with `nix build .#checks.x86_64-linux.agent-permissions`.

## WSL networking and authentication

`config/wslconfig` selects Consomme. Mirrored mode previously dropped the guest's
default route on Wi-Fi NIC events, so switching back can reintroduce that problem.

Firebase's browser login normally opens a dual-stack `[::]` callback listener.
Consomme currently refuses IPv4 connections to that listener and hangs forwarding
IPv6 from Windows ([WSL#41860](https://github.com/microsoft/WSL/issues/41860)).
`home/home.nix` patches Firebase to listen on `127.0.0.1` instead; both
`firebase login --reauth` and `gcloud-reauth` use that package. Firebase also
picks its port by binding and instantly closing it on every local address.
Consomme keeps a phantom listener for each probe for about a minute, and a real
bind that follows on the same port is silently moved to a random port when one
side is a wildcard and the other a specific address of the same family (0.0.0.0
against 127.0.0.1, `::` against `::1`). The login redirect to `localhost:9005`
then finds nothing and the CLI waits forever, so the patch probes only
`127.0.0.1`. The substitutions fail the build if upstream changes either spot,
so the workaround gets reviewed on upgrades. Before rebuilding,
`firebase login --reauth --no-localhost` bypasses the callback entirely using
Firebase's supported code-paste flow. Agent shells get that flow regardless:
Firebase treats `CLAUDECODE` and similar variables as non-interactive. Run the
login from a normal pane, or add `--interactive`.

gcloud's browser logins listen on `127.0.0.1:8085` and redirect to
`localhost:8085`. Since SDK 591, the vendored google-auth-oauthlib also reserves
`::1:8085` with `bind()` and no `listen()`, so a browser that tries `::1` first
is refused and falls back to `127.0.0.1`. Consomme mirrors that bind as a Windows
`[::1]` listener that accepts and never forwards, so Windows Chrome hangs on
`::1` and the login waits forever. `home/google-cloud-sdk.nix` patches the
redirect host to `127.0.0.1`, which skips both the reservation and `::1`. Google
accepts it for both gcloud clients. The substitution fails the build if upstream
changes it. To spot this, run `netstat.exe -ano` from WSL and look for a
`dllhost` `[::1]:<port>` listener. `ss -ltn` won't show the guest socket, because
it lists only listening sockets. Don't connect to the callback port while a login
is waiting, because gcloud serves only one request. On an unpatched build,
change `localhost` to `127.0.0.1` in the hanging tab's URL.

Node dev servers hit the same wall. `listen(port)` with no host binds `[::]`, so
Windows Chrome gets `ERR_CONNECTION_REFUSED` from, for example,
`https://app-local.dev.bookcreator.com:3000`. `config/node/ipv4-listen.js` is
preloaded into every Node process started from zsh (`NODE_OPTIONS`, set in
`home/shell.nix`) and makes a host-less `listen` bind `0.0.0.0` instead. Servers
that pass a host are untouched and `NODE_LISTEN_DUALSTACK=1` switches the shim
off. It does not cover servers that are not Node, or Node started outside zsh or
with its own `NODE_OPTIONS`. The `*-local.dev.bookcreator.com` names point at
localhost through `networking.hosts` on thixos and, for Windows, through the
`--host-resolver-rules` flag on the Chrome (DevTools MCP) shortcut. If a server
reports one port and `ss -ltn` shows another, a probe on a different address
poisoned it; wait a minute or probe and bind the same address.

For a complete outage, collect evidence **before** restarting anything. Home
Manager installs a Windows-side tool that remains available when WSL is broken.
Run from Windows PowerShell after rebuilding. Windows blocks scripts by default,
so bypass the execution policy for this one process:

```powershell
powershell -NoProfile -ExecutionPolicy Bypass -File "$env:LOCALAPPDATA\wsl-network\wsl-network.ps1"
```

Reports go to `%LOCALAPPDATA%\wsl-network\reports`. They compare Windows and
guest HTTPS requests by hostname and IP, and record routes, DNS ownership,
firewall policy, host services and recent Windows networking errors. Individual
WSL commands time out so a stuck guest does not block the rest of the report.
Use `-Distro <name>` if the distro was imported under another name.

If only hostname requests fail, inspect DNS: WSL and Tailscale have both been
observed rewriting `/etc/resolv.conf`. If guest requests to IPs fail while the
Windows probes work, the WSL backend or filtering path is implicated. If both
fail, investigate the Windows connection; Windows logged Wi-Fi limited-connectivity
recovery and DNS timeouts during the October 2026 investigation. A healthy
snapshot had outbound/loopback allowed and no explicit Windows block rules;
this does not establish what happened during an earlier outage.

To try recovery without rebooting Windows, save work in **all** WSL distros,
then run from **elevated Windows PowerShell**:

```powershell
powershell -NoProfile -ExecutionPolicy Bypass -File "$env:LOCALAPPDATA\wsl-network\wsl-network.ps1" -Recover
```

This captures a report, runs `wsl --shutdown`, then restarts the Windows
`WslService` (or legacy `LxssManager`). Terminating/rebooting one guest leaves
host services running. Reopen WSL and run the report again to check recovery.
The service restart is a recovery attempt; the intermittent outage's cause
has not yet been reproduced. Firewall policy is unchanged.

## Embedded debug probes (USB/IP passthrough)

`thixos` forwards a USB debug probe from Windows into WSL over USB/IP, so you can
flash/debug ARM/RISC-V targets (e.g. a Pico running `debugprobe` firmware wired to
a target Pico 2 / RP2350 over SWD). `nixos/embedded.nix` provides **only the USB
plumbing**: the `wsl.usbip` client, the `vhci_hcd` kernel module, an auto-attach
service, and a udev rule giving `thom` (via `plugdev`) non-root access to the probe.
**The toolchain (probe-rs etc.) lives in your project's devshell, not the system.**

### One-time setup

On Windows (admin PowerShell) — install the USB/IP daemon and share the probe:
```powershell
winget install usbipd
usbipd list                  # note the BUSID of your probe, e.g. 3-1
usbipd bind --busid <BUSID>  # plain bind — NOT --force (see Troubleshooting)
```
Set `autoAttach = [ "<BUSID>" ];` in `nixos/embedded.nix`, rebuild, then restart
WSL once (the restart loads `vhci_hcd` and applies the `plugdev` group):
```shell
sudo nixos-rebuild switch --flake ~/src/github.com/tteggel/.dotfiles#thixos
```
```powershell
wsl --shutdown               # from Windows; reopen thixos afterwards
```

### Day-to-day (hands-off)

Nothing — a systemd service (`usbip-auto-attach@<BUSID>`) polls every second and
(re)attaches the probe across boots, replugs and resets. Confirm with `lsusb`
(probe shows up, e.g. `2e8a:000c`). Manual override: `usbip-attach [VID:PID]`.

### The toolchain (in your project, not the dotfiles)

probe-rs is intentionally not system-installed — add it to the project devshell:
```nix
devShells.default = pkgs.mkShell {
  packages = [ pkgs.probe-rs-tools /* + rust toolchain, flip-link, … */ ];
};
```
Then `probe-rs list` sees the probe (via the system udev rule) and you flash with
`probe-rs run --chip RP235x <elf>` (`probe-rs chip list | grep -i rp235` for the
exact chip name).

### Troubleshooting (lessons learned)

- **Never `usbipd bind --force`.** It permanently swaps the device onto usbipd's
  VBoxUSB stub driver; it then flip-flops ("Shared (forced)" toggling) and the WSL
  attach alternates *"Device in error state"/"not found"*. Use plain `bind`. To
  recover a stuck device: Device Manager → Uninstall device → unplug/replug, then
  plain `bind`. If plain `bind` won't hold, a USB filter driver (real VirtualBox, or
  RDP/AV USB redirection) is claiming it — remove that.
- **Not in `lsusb`, `usbip port` says "is vhci_hcd loaded?"** → the module didn't
  load. It's `boot.kernelModules = [ "vhci_hcd" ]`; needs a `wsl --shutdown` (or
  `sudo modprobe vhci_hcd` to load immediately).
- **Can't reach the server** (`usbip list -r 127.0.0.1` fails) → Windows Firewall
  rule for TCP 3240. `snippetIpAddress = "127.0.0.1"` assumes WSL shares Windows'
  localhost — true for consomme (which `config/wslconfig` sets) and mirrored
  networking; NAT mode uses the eth0 gateway instead.
- No custom kernel is built — USB/IP rides the stock WSL2 kernel. *"WSL kernel is
  not USBIP capable"* → `wsl --update`.
- **Same port**: `bind`/`autoAttach` key on the physical port (busid); a different
  port needs a one-time `bind` + `autoAttach` update.

