    const UNIFORMS_OFFSET: usize = 65408;

    fn write_uniforms(&self, store: &mut wasmi::Store<()>, uniforms: &ShaderUniforms) {
        let bytes: &[u8] = unsafe {
            core::slice::from_raw_parts(
                uniforms as *const ShaderUniforms as *const u8,
                128,
            )
