        }
        // Call shade_batch
        self.shade_batch.call(&mut *store, (data_offset as i32, count as i32)).ok()?;
        // Read back results
        let mem_data = self.memory.data(&*store);
        let mut results = Vec::with_capacity(count);
        for i in 0..count {
