    let c = c / 255.0;
    if c <= 0.04045 {
        c / 12.92
    } else {
        powf((c + 0.055) / 1.055, 2.4)
    }
}

fn linear_to_srgb(c: f32) -> f32 {
    let c = clamp(c, 0.0, 1.0);
    if c <= 0.0031308 {
        c * 12.92
    } else {
        1.055 * powf(c, 1.0 / 2.4) - 0.055
    }
}

fn rgb_to_oklch(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let rl = srgb_to_linear(r);
    let gl = srgb_to_linear(g);
    let bl = srgb_to_linear(b);

    let l_ = 0.4122214708 * rl + 0.5363325363 * gl + 0.0514459929 * bl;
    let m_ = 0.2119034982 * rl + 0.6806995451 * gl + 0.1073969566 * bl;
    let s_ = 0.0883024619 * rl + 0.2817188376 * gl + 0.6299787005 * bl;

    let l_ = cbrtf(l_);
    let m_ = cbrtf(m_);
    let s_ = cbrtf(s_);

    let lab_l = 0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_;
    let lab_a = 1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_;
    let lab_b = 0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_;

    let c = sqrtf(lab_a * lab_a + lab_b * lab_b);
    let mut h = atan2f(lab_b, lab_a) * (180.0 / core::f32::consts::PI);
    if h < 0.0 {
        h += 360.0;
    }
    (lab_l, c, h)
}

fn oklch_to_rgb(l: f32, c: f32, h: f32) -> (f32, f32, f32) {
    let h_rad = h * (core::f32::consts::PI / 180.0);
    let lab_a = c * cosf(h_rad);
    let lab_b = c * sinf(h_rad);

    let l_ = l + 0.3963377774 * lab_a + 0.2158037573 * lab_b;
    let m_ = l - 0.1055613458 * lab_a - 0.0638541728 * lab_b;
    let s_ = l - 0.0894841775 * lab_a - 1.2914855480 * lab_b;

    let l_ = l_ * l_ * l_;
    let m_ = m_ * m_ * m_;
    let s_ = s_ * s_ * s_;

    let rl = 4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_;
    let gl = -1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_;
    let bl = -0.0041960863 * l_ - 0.7034186147 * m_ + 1.7076147010 * s_;

    (
        linear_to_srgb(rl) * 255.0,
        linear_to_srgb(gl) * 255.0,
        linear_to_srgb(bl) * 255.0,
    )
}

// --- no_std math helpers ---

fn clamp(x: f32, lo: f32, hi: f32) -> f32 {
    if x < lo {
        lo
    } else if x > hi {
        hi
    } else {
        x
    }
}

fn absf(x: f32) -> f32 {
    if x < 0.0 { -x } else { x }
}

fn maxf(a: f32, b: f32) -> f32 {
    if a > b { a } else { b }
}

// Approximate sqrt via Newton's method
fn sqrtf(x: f32) -> f32 {
    if x <= 0.0 {
        return 0.0;
    }
    let i = x.to_bits();
    let i = 0x1FBD1DF5 + (i >> 1);
    let mut y = f32::from_bits(i);
    y = 0.5 * (y + x / y);
    y = 0.5 * (y + x / y);
    y = 0.5 * (y + x / y);
    y
}

// Approximate cbrt
fn cbrtf(x: f32) -> f32 {
    if x == 0.0 {
        return 0.0;
    }
    let sign = if x < 0.0 { -1.0f32 } else { 1.0f32 };
    let x = absf(x);
    let i = x.to_bits();
    let i = i / 3 + 0x2A508C2F;
    let mut y = f32::from_bits(i);
    y = y - (y * y * y - x) / (3.0 * y * y);
    y = y - (y * y * y - x) / (3.0 * y * y);
    y = y - (y * y * y - x) / (3.0 * y * y);
    sign * y
}

fn powf(base: f32, exp: f32) -> f32 {
    if base <= 0.0 {
        return 0.0;
    }
    exp2f(exp * log2f(base))
}

fn log2f(x: f32) -> f32 {
    if x <= 0.0 {
        return -1e30;
    }
    let bits = x.to_bits();
    let exponent = ((bits >> 23) & 0xFF) as i32 - 127;
    let m_bits = (bits & 0x007FFFFF) | 0x3F800000;
    let m = f32::from_bits(m_bits);
    let a = m - 1.0;
    let log2_m = a * (1.4426950408 - a * (0.7213475 - a * 0.4808983));
    exponent as f32 + log2_m
}

fn exp2f(x: f32) -> f32 {
    if x < -126.0 {
        return 0.0;
    }
    if x > 127.0 {
        return f32::MAX;
    }
    let xi = x as i32 - if x < 0.0 { 1 } else { 0 };
    let xf = x - xi as f32;
    let two_xf = 1.0 + xf * (0.6931472 + xf * (0.2402265 + xf * (0.0555041 + xf * 0.009618)));
    let bits = ((xi + 127) as u32) << 23;
    f32::from_bits(bits) * two_xf
}

fn sinf(x: f32) -> f32 {
    let mut x = x;
    const TWO_PI: f32 = 2.0 * core::f32::consts::PI;
    let n = (x / TWO_PI) as i32;
    x = x - (n as f32) * TWO_PI;
    if x > core::f32::consts::PI {
        x -= TWO_PI;
    } else if x < -core::f32::consts::PI {
        x += TWO_PI;
    }
    let x2 = x * x;
    let x3 = x2 * x;
    let x5 = x3 * x2;
    let x7 = x5 * x2;
    x - x3 / 6.0 + x5 / 120.0 - x7 / 5040.0
}

fn cosf(x: f32) -> f32 {
    sinf(x + core::f32::consts::FRAC_PI_2)
}

fn atan2f(y: f32, x: f32) -> f32 {
    if x == 0.0 {
        if y > 0.0 {
            return core::f32::consts::FRAC_PI_2;
        } else if y < 0.0 {
            return -core::f32::consts::FRAC_PI_2;
        } else {
            return 0.0;
        }
    }
    let a = atanf(y / x);
    if x > 0.0 {
        a
    } else if y >= 0.0 {
        a + core::f32::consts::PI
    } else {
        a - core::f32::consts::PI
    }
}

fn atanf(x: f32) -> f32 {
    if absf(x) > 1.0 {
        let sign = if x > 0.0 { 1.0 } else { -1.0 };
        return sign * core::f32::consts::FRAC_PI_2 - atanf(1.0 / x);
    }
    let x2 = x * x;
    x * (1.0 - x2 * (0.3333333 - x2 * (0.2 - x2 * 0.142857)))
}

// --- Uniforms ---
//
// Only pane_width and pane_height are read by this static shader.
// The host still writes a full uniforms block at WASM memory offset 65408
// (128 bytes); fields beyond the two we use are ignored.

struct Uniforms {
    w: f32,
    h: f32,
}

const UNIFORMS_OFFSET: usize = 65408;

fn read_uniforms() -> Uniforms {
    unsafe {
        let o = UNIFORMS_OFFSET;
        Uniforms {
            w: maxf(read_i32(o) as f32, 1.0),
            h: maxf(read_i32(o + 4) as f32, 1.0),
        }
    }
}

// --- Shader entry points ---

// Host writes uniforms at offset 65408, then color entries at colors_ptr.
// Each color entry: 6 x i32 (24 bytes) = [r, g, b, x, y, is_fg].
// shade_batch transforms r,g,b in-place.
#[no_mangle]
pub extern "C" fn shade_batch(colors_ptr: i32, count: i32) {
    let u = read_uniforms();
    let ptr = colors_ptr as usize;
    let count = count as usize;

    for i in 0..count {
        let base = ptr + i * 24;
        unsafe {
            let r = read_i32(base) as f32;
            let g = read_i32(base + 4) as f32;
            let b = read_i32(base + 8) as f32;
            let x = read_i32(base + 12) as f32;
            let y = read_i32(base + 16) as f32;
            let is_fg = read_i32(base + 20) != 0;

            let (nr, ng, nb) = shade(r, g, b, x, y, is_fg, &u);

            write_i32(base, nr as i32);
            write_i32(base + 4, ng as i32);
            write_i32(base + 8, nb as i32);
        }
    }
}

// invalidate() intentionally not exported. The simplified fork drops
// animation-tick plumbing entirely; the shader runs once per render and
// produces a static result.

unsafe fn read_i32(addr: usize) -> i32 {
    core::ptr::read(addr as *const i32)
}

unsafe fn write_i32(addr: usize, val: i32) {
    core::ptr::write(addr as *mut i32, val);
}

fn shade(
    r: f32, g: f32, b: f32,
    x: f32, y: f32,
    is_fg: bool,
    u: &Uniforms,
) -> (f32, f32, f32) {
    let (l, c, hue) = rgb_to_oklch(r, g, b);

    // Pane-local coordinates.
    let lx = x % u.w;
    let ly = y % u.h;

    // Vignette: subtle edge darkening.
    let nx = lx / u.w;
    let ny = ly / u.h;
    let vx = (nx - 0.5) * 2.0;
    let vy = (ny - 0.5) * 2.0;
    let vdist = sqrtf(vx * vx + vy * vy);
    let vignette = clamp(1.2 - vdist * 0.4, 0.55, 1.0);

    let nl = clamp(l * vignette, 0.0, 1.0);

    if is_fg {
        let nc = c * 0.18;
        let (or_, og, ob) = oklch_to_rgb(nl, nc, hue);
        (clamp(or_, 0.0, 255.0), clamp(og, 0.0, 255.0), clamp(ob, 0.0, 255.0))
    } else {
        let nc = c * 0.25;
        let (or_, og, ob) = oklch_to_rgb(nl, nc, hue);
        (clamp(or_, 0.0, 255.0), clamp(og, 0.0, 255.0), clamp(ob, 0.0, 255.0))
    }
}
// Rules for deciding which neighbouring code points belong to one user-visible character
// (a grapheme cluster: a letter with its accents, an emoji sequence, an Indic conjunct).
//
// The grid calls into this for every printed character, so the answer has to be cheap in the
// common case. It is computed in two steps:
//
// 1. A fast pre-check, `may_join`, built on `join_class` and the JOIN_CLASS_BLOCKS /
//    JOIN_CLASS_TABLE tables. It looks at a single pair of code points and answers "these
//    can't be one character" or "these might be". Plain text (ASCII, Latin, CJK) is
//    rejected in a few instructions.
// 2. The real answer, `is_boundary_at`, which asks unicode-segmentation whether the Unicode
//    rules put a boundary at that position. It is comparatively expensive, so it only runs
//    for pairs the pre-check lets through.
//
// The pre-check must never say "no" for a pair that Unicode joins, because then the real
// check is never asked and the pair is split. Saying "maybe" too often only costs time. The
// test `the_join_pre_check_never_misses_a_pair_without_a_boundary` compares the two on a
// sample of code points; the tables have to be extended when a newer Unicode version
// (through a newer unicode-segmentation) adds joining code points.
//
// Users:
// - `Grid::print` (grid.rs): `width_and_may_group` for every character; in grapheme mode
//   `may_join` + `is_boundary_at` decide whether to attach a code point to the previous cell.
// - output/mod.rs: `group_end` finds multi-cell groups when serializing rows to clients,
//   `prepare_unit` decides how to write each unit to a host terminal.
// - selection (grid.rs): `unit_column_spans` widens a selection to whole units.
// - search.rs: `is_boundary_at` keeps matches on cluster boundaries.
// - zellij-terminal's reference.rs: `group_end` and `prepare_unit` to mirror the server output.
use unicode_segmentation::GraphemeCursor;
use unicode_width::UnicodeWidthChar;

// Bit flags stored per code point range in JOIN_CLASS_TABLE and returned by `join_class`.
// JOINS_RIGHT: may join whatever follows it (ZWJ, regional indicators, Indic viramas).
pub const JOINS_RIGHT: u8 = 1;
// JOINS_LEFT: may join whatever precedes it even though it has its own width (spacing marks
// such as Devanagari vowel signs, regional indicators).
pub const JOINS_LEFT: u8 = 2;
// EXTEND: a Unicode "Extend" code point that joins the code point before it (combining
// marks, variation selectors, emoji skin tone modifiers, the keycap combiner, tag
// characters).
pub const EXTEND: u8 = 4;
// CONSONANT: an Indic consonant that can join a preceding virama or mark into a conjunct.
pub const CONSONANT: u8 = 8;

// Returns the JOIN_* flags of a code point, or 0 if it never takes part in joining.
// Everything below U+0300 returns 0 immediately; the block bitmap rejects most other code
// points with one bit test before the table is searched.

#[inline(always)]
pub fn join_class(c: char) -> u8 {
    let c = c as u32;
    if c < 0x300 {
        return 0;
    }
    let block = (c >> 7) as usize;
    if JOIN_CLASS_BLOCKS[block >> 6] & (1u64 << (block & 63)) == 0 {
        return 0;
    }
    match JOIN_CLASS_TABLE.binary_search_by(|&(lo, hi, _)| {
        if c < lo {
            std::cmp::Ordering::Greater
        } else if c > hi {
            std::cmp::Ordering::Less
        } else {
            std::cmp::Ordering::Equal
        }
    }) {
        Ok(index) => JOIN_CLASS_TABLE[index].2,
        Err(_) => 0,
    }
}

#[inline]
fn is_wide_extend(c: char, class: u8) -> bool {
    class & EXTEND != 0 && c.width().unwrap_or(0) != 0
}

// The fast pre-check: can `right_first` belong to the same cluster as a cell ending in
// `left_last`? `false` is definite; `true` means "ask `is_boundary_at`".
#[inline]
pub fn may_join(left_last: char, right_first: char) -> bool {
    if (left_last as u32) < 0x300 && (right_first as u32) < 0x300 {
        return false;
    }
    let left = join_class(left_last);
    if left & JOINS_RIGHT != 0 {
        return true;
    }
    let right = join_class(right_first);
    if right & JOINS_LEFT != 0 || is_wide_extend(right_first, right) {
        return true;
    }
    right & CONSONANT != 0 && (left & EXTEND != 0 || left_last.width() == Some(0))
}

// Ranges of two-column characters (hiragana, katakana, CJK ideographs) that never join a
// neighbour, so the printing fast path can give them width 2 without any lookup. Kept as data
// so tests can check every code point in them; `is_plain_wide` is the hard-coded copy used at
// runtime.
pub const PLAIN_WIDE_RANGES: [(u32, u32); 4] = [
    (0x3041, 0x3096),
    (0x30A1, 0x30FA),
    (0x3400, 0x4DBF),
    (0x4E00, 0x9FFF),
];

// True for the PLAIN_WIDE_RANGES above.
#[inline(always)]
pub fn is_plain_wide(c: char) -> bool {
    matches!(c as u32, 0x3041..=0x3096 | 0x30A1..=0x30FA | 0x3400..=0x4DBF | 0x4E00..=0x9FFF)
}

// Whether a freshly printed cell starting with `first` might form a group with a
// neighbouring cell. The grid uses it to set `Row::may_have_groups`, so rows without such
// characters skip group detection when they are serialized.
#[inline(always)]
pub fn new_cell_may_join_a_neighbour(first: char) -> bool {
    if (first as u32) < 0x300 {
        return false;
    }
    let class = join_class(first);
    class & (JOINS_LEFT | JOINS_RIGHT) != 0 || is_wide_extend(first, class)
}

// Width of a printed character plus whether it might group with a neighbour, in one call.
// Printable ASCII and plain CJK return without any table lookup; this is the hot path of
// `Grid::print`.
#[inline(always)]
pub fn width_and_may_group(c: char) -> (usize, bool) {
    if (' '..='~').contains(&c) {
        (1, false)
    } else if is_plain_wide(c) {
        (2, false)
    } else {
        match c.width().unwrap_or(0) {
            0 => (0, false),
            width => (width, new_cell_may_join_a_neighbour(c)),
        }
    }
}

// Whether a code point attached to a cell (e.g. a ZWJ at the end of "👨‍") means the cell may
// join the next cell, so the row has to be marked as possibly holding groups.
#[inline]
pub fn attached_may_join_right(c: char) -> bool {
    join_class(c) & JOINS_RIGHT != 0
}

// The real answer: is there a grapheme cluster boundary at byte `offset` of `text`, per
// unicode-segmentation (extended grapheme clusters)? Offsets at either end are boundaries.
pub fn is_boundary_at(text: &str, offset: usize) -> bool {
    if offset == 0 || offset >= text.len() {
        return true;
    }
    let mut cursor = GraphemeCursor::new(offset, text.len(), true);
    cursor.is_boundary(text, 0).unwrap_or(true)
}

