#![no_std]

#[panic_handler]
fn panic(_info: &core::panic::PanicInfo) -> ! {
    core::arch::wasm32::unreachable()
}

// --- Color space math ---

fn srgb_to_linear(c: f32) -> f32 {
    let c = c / 255.0;
    if c <= 0.04045 {
        c / 12.92
    } else {
        powf((c + 0.055) / 1.055, 2.4)
    }
}

fn linear_to_srgb(c: f32) -> f32 {
    let c = clamp(c, 0.0, 1.0);
    if c <= 0.0031308 {
        c * 12.92
    } else {
        1.055 * powf(c, 1.0 / 2.4) - 0.055
    }
}

fn rgb_to_oklch(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let rl = srgb_to_linear(r);
    let gl = srgb_to_linear(g);
    let bl = srgb_to_linear(b);

    let l_ = 0.4122214708 * rl + 0.5363325363 * gl + 0.0514459929 * bl;
    let m_ = 0.2119034982 * rl + 0.6806995451 * gl + 0.1073969566 * bl;
    let s_ = 0.0883024619 * rl + 0.2817188376 * gl + 0.6299787005 * bl;

    let l_ = cbrtf(l_);
    let m_ = cbrtf(m_);
    let s_ = cbrtf(s_);

    let lab_l = 0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_;
    let lab_a = 1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_;
    let lab_b = 0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_;

    let c = sqrtf(lab_a * lab_a + lab_b * lab_b);
    let mut h = atan2f(lab_b, lab_a) * (180.0 / core::f32::consts::PI);
    if h < 0.0 {
        h += 360.0;
    }
    (lab_l, c, h)
}

fn oklch_to_rgb(l: f32, c: f32, h: f32) -> (f32, f32, f32) {
    let h_rad = h * (core::f32::consts::PI / 180.0);
    let lab_a = c * cosf(h_rad);
    let lab_b = c * sinf(h_rad);

    let l_ = l + 0.3963377774 * lab_a + 0.2158037573 * lab_b;
    let m_ = l - 0.1055613458 * lab_a - 0.0638541728 * lab_b;
    let s_ = l - 0.0894841775 * lab_a - 1.2914855480 * lab_b;

    let l_ = l_ * l_ * l_;
    let m_ = m_ * m_ * m_;
    let s_ = s_ * s_ * s_;

    let rl = 4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_;
    let gl = -1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_;
    let bl = -0.0041960863 * l_ - 0.7034186147 * m_ + 1.7076147010 * s_;

    (
        linear_to_srgb(rl) * 255.0,
        linear_to_srgb(gl) * 255.0,
        linear_to_srgb(bl) * 255.0,
    )
}

// --- no_std math helpers ---

fn clamp(x: f32, lo: f32, hi: f32) -> f32 {
    if x < lo {
        lo
    } else if x > hi {
        hi
    } else {
        x
    }
}

fn absf(x: f32) -> f32 {
    if x < 0.0 { -x } else { x }
}

fn maxf(a: f32, b: f32) -> f32 {
    if a > b { a } else { b }
}

// Approximate sqrt via Newton's method
fn sqrtf(x: f32) -> f32 {
    if x <= 0.0 {
        return 0.0;
    }
    let i = x.to_bits();
    let i = 0x1FBD1DF5 + (i >> 1);
    let mut y = f32::from_bits(i);
    y = 0.5 * (y + x / y);
    y = 0.5 * (y + x / y);
    y = 0.5 * (y + x / y);
    y
}

// Approximate cbrt
fn cbrtf(x: f32) -> f32 {
    if x == 0.0 {
        return 0.0;
    }
    let sign = if x < 0.0 { -1.0f32 } else { 1.0f32 };
    let x = absf(x);
    let i = x.to_bits();
    let i = i / 3 + 0x2A508C2F;
    let mut y = f32::from_bits(i);
    y = y - (y * y * y - x) / (3.0 * y * y);
    y = y - (y * y * y - x) / (3.0 * y * y);
    y = y - (y * y * y - x) / (3.0 * y * y);
    sign * y
}

fn powf(base: f32, exp: f32) -> f32 {
    if base <= 0.0 {
        return 0.0;
    }
    exp2f(exp * log2f(base))
}

fn log2f(x: f32) -> f32 {
    if x <= 0.0 {
        return -1e30;
    }
    let bits = x.to_bits();
    let exponent = ((bits >> 23) & 0xFF) as i32 - 127;
    let m_bits = (bits & 0x007FFFFF) | 0x3F800000;
    let m = f32::from_bits(m_bits);
    let a = m - 1.0;
    let log2_m = a * (1.4426950408 - a * (0.7213475 - a * 0.4808983));
    exponent as f32 + log2_m
}

fn exp2f(x: f32) -> f32 {
    if x < -126.0 {
        return 0.0;
    }
    if x > 127.0 {
        return f32::MAX;
    }
    let xi = x as i32 - if x < 0.0 { 1 } else { 0 };
    let xf = x - xi as f32;
    let two_xf = 1.0 + xf * (0.6931472 + xf * (0.2402265 + xf * (0.0555041 + xf * 0.009618)));
    let bits = ((xi + 127) as u32) << 23;
    f32::from_bits(bits) * two_xf
}

fn sinf(x: f32) -> f32 {
    let mut x = x;
    const TWO_PI: f32 = 2.0 * core::f32::consts::PI;
    let n = (x / TWO_PI) as i32;
    x = x - (n as f32) * TWO_PI;
    if x > core::f32::consts::PI {
        x -= TWO_PI;
    } else if x < -core::f32::consts::PI {
        x += TWO_PI;
    }
    let x2 = x * x;
    let x3 = x2 * x;
    let x5 = x3 * x2;
    let x7 = x5 * x2;
    x - x3 / 6.0 + x5 / 120.0 - x7 / 5040.0
}

fn cosf(x: f32) -> f32 {
    sinf(x + core::f32::consts::FRAC_PI_2)
}

fn atan2f(y: f32, x: f32) -> f32 {
    if x == 0.0 {
        if y > 0.0 {
            return core::f32::consts::FRAC_PI_2;
        } else if y < 0.0 {
            return -core::f32::consts::FRAC_PI_2;
        } else {
            return 0.0;
        }
    }
    let a = atanf(y / x);
    if x > 0.0 {
        a
    } else if y >= 0.0 {
        a + core::f32::consts::PI
    } else {
        a - core::f32::consts::PI
    }
}

fn atanf(x: f32) -> f32 {
    if absf(x) > 1.0 {
        let sign = if x > 0.0 { 1.0 } else { -1.0 };
        return sign * core::f32::consts::FRAC_PI_2 - atanf(1.0 / x);
    }
    let x2 = x * x;
    x * (1.0 - x2 * (0.3333333 - x2 * (0.2 - x2 * 0.142857)))
}

// --- Uniforms ---
//
// Only pane_width and pane_height are read by this static shader.
// The host still writes a full uniforms block at WASM memory offset 65408
// (128 bytes); fields beyond the two we use are ignored.

struct Uniforms {
    w: f32,
    h: f32,
}

impl From<ThemeHue> for HostTerminalThemeMode {
    fn from(hue: ThemeHue) -> Self {
        match hue {
            ThemeHue::Light => HostTerminalThemeMode::Light,
            ThemeHue::Dark => HostTerminalThemeMode::Dark,
        }
    }
}

impl From<HostTerminalThemeMode> for ThemeHue {
    fn from(mode: HostTerminalThemeMode) -> Self {
        match mode {
            HostTerminalThemeMode::Light => ThemeHue::Light,
            HostTerminalThemeMode::Dark => ThemeHue::Dark,
        }
    }
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq, Hash)]
pub enum PaletteColor {
    Rgb((u8, u8, u8)),
    EightBit(u8),
}
impl Default for PaletteColor {
    fn default() -> PaletteColor {
        PaletteColor::EightBit(0)
    }
}

/// Priority layer for plugin-supplied regex highlights.
/// Higher-priority layers take visual precedence over lower ones
/// when highlights overlap.  Built-in highlights (mouse selection,
/// search results) always take precedence over all plugin layers.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub enum HighlightLayer {
    Hint,           // lowest: pure pattern matching (paths, URLs, IPs)
    Tool,           // middle: backed by runtime domain knowledge (git, docker, k8s)
    ActionFeedback, // highest: result of an explicit user action (search, bookmarks)
}

impl Default for HighlightLayer {
    fn default() -> Self {
        HighlightLayer::Hint
    }
}

/// Style for a plugin-supplied regex highlight.
/// Theme-based variants reference `style.colors.text_unselected.*`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum HighlightStyle {
    None,      // no color override — use with bold/italic/underline for style-only highlights
    Emphasis0, // fg = emphasis_0, no bg override
    Emphasis1, // fg = emphasis_1, no bg override
    Emphasis2, // fg = emphasis_2, no bg override
    Emphasis3, // fg = emphasis_3, no bg override
    BackgroundEmphasis0, // bg = emphasis_0, fg = background
    BackgroundEmphasis1, // bg = emphasis_1, fg = background
    BackgroundEmphasis2, // bg = emphasis_2, fg = background
    BackgroundEmphasis3, // bg = emphasis_3, fg = background
    CustomRgb {
        fg: Option<(u8, u8, u8)>,
        bg: Option<(u8, u8, u8)>,
    },
    CustomIndex {
        fg: Option<u8>,
        bg: Option<u8>,
    },
}

/// One pattern + style pair sent by a plugin.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RegexHighlight {
    pub pattern: String, // key for upsert; also the regex source
    pub style: HighlightStyle,
    pub layer: HighlightLayer,
    pub context: BTreeMap<String, String>, // arbitrary data echoed back verbatim on click
    pub on_hover: bool, // if true, only rendered when the cursor overlaps this match
    pub bold: bool,
    pub italic: bool,
    pub underline: bool,
    pub tooltip_text: Option<String>, // shown at bottom of pane frame when hovering over match
}

// these are used for the web client
impl PaletteColor {
    pub fn as_rgb_str(&self) -> String {
        let (r, g, b) = match *self {
            Self::Rgb((r, g, b)) => (r, g, b),
            Self::EightBit(c) => eightbit_to_rgb(c),
        };
        format!("rgb({}, {}, {})", r, g, b)
    }
